// All sounds are generated by the browser — no audio files needed.
let ctx = null;
let master = null;
let muted = false;
try { muted = JSON.parse(localStorage.getItem('solarSettings') || '{}').muted === true; } catch (e) { /* ignore */ }

function ensure() {
  if (ctx) return ctx;
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return null;
  ctx = new AC();
  master = ctx.createGain();
  master.gain.value = muted ? 0 : 0.6;
  master.connect(ctx.destination);
  startAmbient();
  return ctx;
}

// Browsers only allow sound after the first tap
export function unlock() {
  const c = ensure();
  if (c && c.state === 'suspended') c.resume();
}

export function setMuted(m) {
  muted = m;
  if (master) master.gain.setTargetAtTime(m ? 0 : 0.6, ctx.currentTime, 0.1);
}
export const isMuted = () => muted;

function tone(freq, dur, vol, type = 'sine', when = 0, slideTo = null) {
  const t = ctx.currentTime + when;
  const o = ctx.createOscillator();
  const g = ctx.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, t);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(vol, t + 0.02);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g);
  g.connect(master);
  o.start(t);
  o.stop(t + dur + 0.05);
}

function noise(dur, vol, fromF, toF) {
  const t = ctx.currentTime;
  const len = Math.floor(ctx.sampleRate * dur);
  const buf = ctx.createBuffer(1, len, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
  const src = ctx.createBufferSource();
  src.buffer = buf;
  const bp = ctx.createBiquadFilter();
  bp.type = 'bandpass';
  bp.Q.value = 0.8;
  bp.frequency.setValueAtTime(fromF, t);
  bp.frequency.exponentialRampToValueAtTime(toF, t + dur);
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(vol, t + 0.15);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(bp);
  bp.connect(g);
  g.connect(master);
  src.start(t);
}

function startAmbient() {
  // Soft space drone
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.value = 500;
  const g = ctx.createGain();
  g.gain.value = 0.06;
  lp.connect(g);
  g.connect(master);
  [55, 82.4, 110.3].forEach((f, i) => {
    const o = ctx.createOscillator();
    o.type = i === 2 ? 'triangle' : 'sine';
    o.frequency.value = f;
    o.detune.value = (i - 1) * 7;
    o.connect(lp);
    o.start();
  });
  const lfo = ctx.createOscillator();
  lfo.frequency.value = 0.06;
  const lg = ctx.createGain();
  lg.gain.value = 220;
  lfo.connect(lg);
  lg.connect(lp.frequency);
  lfo.start();

  // Gentle random chimes
  const notes = [523.25, 587.33, 659.25, 783.99, 880, 1046.5];
  setInterval(() => {
    if (!ctx || muted || ctx.state !== 'running') return;
    if (Math.random() < 0.5) tone(notes[Math.floor(Math.random() * notes.length)], 2.8, 0.025, 'sine');
  }, 3800);
}

export function sfx(name) {
  if (!ctx || muted || ctx.state !== 'running') return;
  switch (name) {
    case 'place': tone(660, 0.15, 0.12, 'triangle'); tone(990, 0.12, 0.06, 'sine', 0.05); break;
    case 'delete': tone(320, 0.22, 0.12, 'triangle', 0, 150); break;
    case 'select': tone(880, 0.08, 0.06); break;
    case 'click': tone(1200, 0.05, 0.05); break;
    case 'undo': tone(520, 0.14, 0.08, 'triangle', 0, 340); break;
    case 'photo': noise(0.15, 0.2, 3000, 6000); break;
    case 'badge': [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => tone(f, 0.45, 0.1, 'triangle', i * 0.1)); break;
    case 'launch': noise(2.6, 0.22, 150, 1600); tone(90, 2.2, 0.08, 'sawtooth', 0, 45); break;
    case 'land': noise(1.4, 0.16, 1400, 180); break;
    case 'whoosh': noise(0.6, 0.12, 400, 2200); break;
  }
}
